import { useState } from 'react'; import { Check, ChevronRight } from 'lucide-react'; import { IndustrialHeader } from './IndustrialHeader';
const IMG_MAL_P1 = 'data:image/jpeg;base64,';
const IMG_MAL_P2 = 'data:image/jpeg;base64,';
interface Props{onComplete:()=>void;elapsedTime:number;toProduct:string;operatorSettings:{operatorName:string;line:string;station:string};onBack:()=>void;onSettings?:()=>void}
export function ChangeoverStep2Screen({onComplete,elapsedTime,toProduct,operatorSettings,onBack,onSettings}:Props){const malImg=toProduct==='Product 1'?IMG_MAL_P1:IMG_MAL_P2;const[checklist,setChecklist]=useState([{id:1,label:'Mal correct gemonteerd',checked:false}]);const toggle=(id:number)=>setChecklist(p=>p.map(i=>i.id===id?{...i,checked:!i.checked}:i));const all=checklist.every(i=>i.checked);return <div className="h-full min-h-0 flex flex-col bg-gray-100 overflow-hidden"><IndustrialHeader title="Omstelling, stap 2 van 5" subtitle={`Mal ${toProduct} plaatsen`} showTimer elapsedTime={elapsedTime} operatorSettings={operatorSettings} onBack={onBack} onSettings={onSettings}/><div className="flex-1 min-h-0 overflow-y-auto flex flex-col md:flex-row p-8 gap-8 max-w-[1280px] mx-auto w-full"><div className="flex-1 bg-white rounded-lg shadow-sm border border-gray-200 p-6"><img src={malImg} alt="Mal plaatsen" className="w-full h-full min-h-72 object-cover rounded-lg"/></div><div className="w-full md:w-96 flex flex-col gap-5"><div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6"><h3 className="text-2xl text-gray-800 font-bold mb-4 uppercase">Plaats {toProduct} mal</h3><p className="text-sm text-gray-700">Neem de klaargelegde mal voor {toProduct} en plaats deze op de vaste positie van de werktafel.</p></div><div className="bg-white rounded-lg shadow-sm border border-gray-200 p-5"><h4 className="text-xs uppercase tracking-wider text-gray-500 mb-3 font-medium">Controleer</h4>{checklist.map(item=><label key={item.id} className="flex items-center gap-3 p-3 bg-gray-50 rounded mb-2"><input type="checkbox" checked={item.checked} onChange={()=>toggle(item.id)} className="w-6 h-6"/><span className="text-sm text-gray-800 flex-1">{item.label}</span>{item.checked&&<Check className="w-5 h-5 text-green-600"/>}</label>)}</div><div className="flex-1"></div><button onClick={onComplete} disabled={!all} className={`w-full text-lg py-4 px-6 rounded-lg flex items-center justify-center gap-3 font-medium ${all?'bg-blue-500 text-white':'bg-gray-300 text-gray-500'}`}>Mal geplaatst<ChevronRight className="w-6 h-6"/></button></div></div></div>}
